printf "import test from 'node:test';
import assert from 'node:assert/strict';
import { mergeCustomers } from '../src/customers.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';

test('mergeCustomers removes from customer and reassigns invoices', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'acme@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Baker', email: 'baker@example.com', tier: 'standard' },
  ];

  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const invoice2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-20',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  }).value;

  const invoices = [invoice1, invoice2];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 1);
  assert.equal(result.value.customers[0].id, 'C-002');
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].customerId, 'C-001');
  assert.equal(result.value.invoices[1].customerId, 'C-001');
});

test('mergeCustomers returns error if from customer not found', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'acme@example.com', tier: 'gold' },
  ];

  const invoices = [];
  const result = mergeCustomers(customers, invoices, 'C-999', 'C-001');

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers returns error if into customer not found', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'acme@example.com', tier: 'gold' },
  ];

  const invoices = [];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-999');

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers returns error for same customer', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'acme@example.com', tier: 'gold' },
  ];

  const invoices = [];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-001');

  assert.deepEqual(result, { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers handles normalized ids', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'acme@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Baker', email: 'baker@example.com', tier: 'standard' },
  ];

  const invoice1 = createInvoice({
    customerId: ' c-001 ',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const invoices = [invoice1];
  const result = mergeCustomers(customers, invoices, ' C-001 ', 'c-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 1);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers with multiple invoices from source', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'acme@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Baker', email: 'baker@example.com', tier: 'standard' },
  ];

  const invoices = [
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    }).value,
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-20',
      lines: [{ sku: 'DEV-HOUR', qty: 5 }],
    }).value,
    createInvoice({
      customerId: 'C-002',
      issueDate: '2024-01-25',
      lines: [{ sku: 'DEV-HOUR', qty: 3 }],
    }).value,
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 3);
  const c001Invoices = result.value.invoices.filter((inv) => inv.customerId === 'C-001');
  assert.equal(c001Invoices.length, 0);
  const c002Invoices = result.value.invoices.filter((inv) => inv.customerId === 'C-001');
  assert.equal(c002Invoices.length, 3);
});

test('mergeCustomers does not mutate inputs', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'acme@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Baker', email: 'baker@example.com', tier: 'standard' },
  ];

  const invoices = [
    createInvoice({
      customerId: 'C-001',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    }).value,
  ];

  const originalCustomersLength = customers.length;
  const originalInvoicesLength = invoices.length;

  mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(customers.length, originalCustomersLength);
  assert.equal(invoices.length, originalInvoicesLength);
  assert.equal(invoices[0].customerId, 'C-001');
});

test('mergeCustomers with no invoices for from customer', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'acme@example.com', tier: 'gold' },
    { id: 'C-002', name: 'Baker', email: 'baker@example.com', tier: 'standard' },
  ];

  const invoices = [
    createInvoice({
      customerId: 'C-002',
      issueDate: '2024-01-15',
      lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    }).value,
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 1);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].customerId, 'C-001');
});

test('mergeCustomers preserves other customer properties', () => {
  const customers = [
    { id: 'C-001', name: 'Acme', email: 'acme@example.com', tier: 'gold', country: 'US' },
    { id: 'C-002', name: 'Baker', email: 'baker@example.com', tier: 'standard', country: 'UK' },
    { id: 'C-003', name: 'Charlie', email: 'charlie@example.com', tier: 'silver', country: 'FR' },
  ];

  const invoices = [];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, 2);
  const charlie = result.value.customers.find((c) => c.id === 'C-003');
  assert.equal(charlie.country, 'FR');
  assert.equal(charlie.tier, 'silver');
});
